package qqmusic

import (
	"os"
	"strings"
	"testing"
)

// 真实上游密文对拍（2026-09-28 本机登录态 sidecar /song/0039MnYb0qxYhV/lyric 抓取，
// 明文 = 晴天 LRC）。防止 3DES 变体移植被「顺手优化」坏。
const qrcLiveFixtureHex = ""

func TestDecryptQRCLiveFixture(t *testing.T) {
	out := DecryptQRC(qrcLiveFixtureHex)
	if !strings.Contains(out, "[ti:晴天]") || !strings.Contains(out, "[00:02.25]") {
		t.Fatalf("歌词解密结果异常: %.120s", out)
	}
}

func TestDecryptQRCDismissesGarbage(t *testing.T) {
	if DecryptQRC("") != "" || DecryptQRC("zzzz") != "" || DecryptQRC("aabb") != "" {
		t.Fatal("脏输入应返回空串而不是报错")
	}
}

func TestDecryptQRCFromFile(t *testing.T) {
	raw, err := os.ReadFile("/home/ne0w0r1d/.cache/go-tmp/lyric_hex.txt")
	if err != nil {
		t.Skip("本地临时 fixture 不存在（CI）")
	}
	out := DecryptQRC(strings.TrimSpace(string(raw)))
	if !strings.Contains(out, "[ti:晴天]") {
		t.Fatalf("fixture 解密失败: %.120s", out)
	}
}
